const row = $input.first().json;

const normalizeBoolean = (value) => value === true || value === 'true' || value === 1 || value === '1';
const severity = String(row.severity ?? '').toLowerCase();
const requiresApproval = normalizeBoolean(row.requires_approval);

return [{
  json: {
    ...row,
    severity,
    requires_approval: requiresApproval,
    skytrace_alert_eligible: requiresApproval || severity === 'critical',
    skytrace_alert_reason: requiresApproval ? 'requires_approval' : severity === 'critical' ? 'critical_severity' : 'not_actionable'
  }
}];

const row = $input.first().json;

const asObject = (value) => {
  if (!value) return {};
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  }
  return {};
};

const payload = asObject(row.payload);
const systemEventPreview = asObject(row.system_event_preview);
const message = String(payload.message ?? payload.summary ?? systemEventPreview.notes ?? 'SkyTrace event requires operator attention.');
const severityLabel = String(row.severity ?? 'unknown').toUpperCase();
const approvalLabel = row.requires_approval ? 'yes' : 'no';

const optionalContext = [
  payload.droneId ? `Drone ID: ${payload.droneId}` : null,
  payload.droneName ? `Drone: ${payload.droneName}` : null,
  payload.zone ? `Zone: ${payload.zone}` : null,
  payload.operator ? `Operator: ${payload.operator}` : null,
  payload.approvalFor ? `Approval for: ${payload.approvalFor}` : null
].filter(Boolean);

const alertLines = [
  'SkyTrace Operational Alert',
  `Mission: ${row.mission_id}`,
  `Event: ${row.event_type}`,
  `Severity: ${severityLabel}`,
  `Status: ${row.status}`,
  `Requires approval: ${approvalLabel}`,
  `Source: ${row.source}`,
  `Event time: ${row.event_timestamp}`,
  `Event ID: ${row.event_id}`,
  ...optionalContext,
  `Message: ${message}`
];

return [{
  json: {
    ...row,
    payload,
    system_event_preview: systemEventPreview,
    skytrace_alert_message: alertLines.join('\n'),
    skytrace_alert_formatted_at: new Date().toISOString(),
    skytrace_alert_channel: 'telegram'
  }
}];

const alert = $('Format Operational Alert').first().json;
const telegramResult = $input.first().json;
const failed = Boolean(telegramResult.error || telegramResult.message?.error || telegramResult.description?.toLowerCase?.().includes('error'));
const messageId = telegramResult.message_id ?? telegramResult.result?.message_id ?? telegramResult.message?.message_id ?? null;

const delivery = {
  ok: !failed,
  delivery_status: failed ? 'failed' : 'sent',
  workflow_name: 'SC - SkyTrace Telegram Alert',
  workflow_key: 'skytrace-telegram-alert',
  channel: 'telegram',
  event_id: alert.event_id,
  mission_id: alert.mission_id,
  event_type: alert.event_type,
  severity: alert.severity,
  requires_approval: alert.requires_approval,
  telegram_message_id: messageId,
  delivered_at: new Date().toISOString(),
  error_message: failed ? String(telegramResult.error?.message ?? telegramResult.description ?? telegramResult.message ?? 'Telegram delivery failed') : null
};

console.log('[SKYTRACE_TELEGRAM_DELIVERY]', delivery);
return [{ json: delivery }];

const delivery = $input.first().json;
return [{
  json: {
    ok: delivery.ok,
    delivery_status: delivery.delivery_status,
    event_id: delivery.event_id,
    mission_id: delivery.mission_id,
    channel: delivery.channel,
    telegram_message_id: delivery.telegram_message_id,
    delivered_at: delivery.delivered_at,
    error_message: delivery.error_message
  }
}];

const row = $input.first().json;
const skipped = {
  ok: true,
  delivery_status: 'skipped',
  workflow_name: 'SC - SkyTrace Telegram Alert',
  workflow_key: 'skytrace-telegram-alert',
  channel: 'telegram',
  event_id: row.event_id,
  mission_id: row.mission_id,
  event_type: row.event_type,
  severity: row.severity,
  requires_approval: row.requires_approval,
  skipped_at: new Date().toISOString(),
  reason: 'Event does not require approval and is not critical'
};

console.log('[SKYTRACE_TELEGRAM_SKIPPED]', skipped);
return [{ json: skipped }];
